import {MAPS,getMap,mapAsset} from './maps.js';
export const currentMap=getMap(new URLSearchParams(location.search).get('map'));
export function setupMapMenu(){let select=document.getElementById('mapSelect'),thumb=document.getElementById('mapThumb');select.innerHTML=MAPS.map(m=>'<option value="'+m.id+'">'+m.id+' · '+m.name+' — '+m.theme+'</option>').join('');select.value=currentMap.id;let preview=()=>{let m=getMap(select.value);thumb.src=mapAsset(m,'thumb.jpg');document.getElementById('mapDescription').textContent=m.theme+' · 四方基地 · 每隊一隻開局';};select.onchange=preview;preview();document.getElementById('applyMap').onclick=()=>{if(select.value!==currentMap.id)location.assign('?map='+select.value);};document.querySelector('.edition').lastElementChild.textContent='香港 · '+currentMap.name;document.querySelector('.scene-note small').textContent='四方地形戰場 · 藝術化地標';document.getElementById('world').setAttribute('aria-label',currentMap.name+'立體競技場');document.querySelector('.scene-note b').textContent=currentMap.id+' / '+currentMap.name;document.querySelector('.brand b').textContent=currentMap.name.replace('區','')+'補給戰';document.querySelector('.brand small').textContent='HONG KONG · SUPPLY BATTLE';document.querySelector('#minimapPanel>span').innerHTML=currentMap.name+'地勢 <i>● 你</i>';document.querySelector('.footer span').textContent=currentMap.name+' / '+currentMap.theme+' / 四方基地';document.title=currentMap.name+' · 四方補給戰 v0.7';}
